const isNetworkError = require('./isNetworkError')
const file = require('./file')
const native = require('./native')
const onepassword = require('./onepassword')
const bitwarden = require('./bitwarden')
const armor = require('./armor')
const approvalRequired = require('./approvalRequired')

// Consumers with custom adapters use this same precedence.
const providerOrder = Object.freeze(['file', 'native', 'armor', 'onepassword', 'bitwarden'])
const factories = { file, armor, native, onepassword, bitwarden }

function provider (options = {}) {
  return {
    async get (publicKey) {
      let armorError
      for (const name of providerOrder) {
        try {
          if (options.onLookup) options.onLookup(name)
          const ring = await factories[name](options).get(publicKey)
          if (ring[publicKey]) return ring
        } catch (error) {
          if (name !== 'armor') throw error
          armorError = error
        } finally {
          if (options.onLookupEnd) options.onLookupEnd(name)
        }
      }
      if (armorError) {
        // CLI consumers may have an interactive fallback after this chain.
        if (options.onArmorError) options.onArmorError(armorError)
        else throw armorError
      }
      return {}
    },
    getSync (publicKey) {
      let armorError
      for (const name of providerOrder) {
        try {
          if (options.onLookup) options.onLookup(name)
          const ring = factories[name](options).getSync(publicKey)
          if (ring[publicKey]) return ring
        } catch (error) {
          if (name !== 'armor') throw error
          armorError = error
        } finally {
          if (options.onLookupEnd) options.onLookupEnd(name)
        }
      }
      if (armorError) {
        // CLI consumers may have an interactive fallback after this chain.
        if (options.onArmorError) options.onArmorError(armorError)
        else throw armorError
      }
      return {}
    }
  }
}

module.exports = { approvalRequired, file, native, onepassword, bitwarden, armor, provider, providerOrder, isNetworkError }
